SELECT clock_timestamp() AS db_at,b.id,b.source_id,b.source_type,b.service_code,b.entry_type,b.event_kind,b.quantity,b.amount,b.reversal_of_id,b.occurred_at,b.created_at,(SELECT sum(l.physical_quantity) FROM billing_ledger_lines l WHERE l.tenant_id=b.tenant_id AND l.ledger_entry_id=b.id) AS physical_quantity,(SELECT sum(l.billing_quantity) FROM billing_ledger_lines l WHERE l.tenant_id=b.tenant_id AND l.ledger_entry_id=b.id) AS billing_quantity FROM billing_ledger_entries b WHERE b.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND b.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND b.source_id IN (SELECT o.id FROM fbs_orders o WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.marketplace='ozon') ORDER BY b.source_id,b.service_code,b.created_at LIMIT 180
